/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Process Price Change tracking records for Products and create Price Data Feed records
/// </summary>
using System.ComponentModel.Composition;
[Export(identifierStr(Dynamics.AX.Application.METPriceChangeTrack))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, Product))]
public class METPriceChangeTrackProduct extends METPriceChangeTrack
{
}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <param name = "_showValidation">Show validation</param>
public void initInstance(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    this.setInternals(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <param name = "_showValidation">Show validation</param>
public void setInternals(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    super(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::Product;
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void process()
    {
        priceDataFeedCount = 0;
        priceDataFeedList = this.createPriceDataFeedList();

        this.processStd();

        if(priceDataFeedCount)
        {
            ttsbegin;
            priceDataFeedList.insertDatabase();
            ttscommit;
        }
    }

/// <summary>
/// Process the Change tracking record
/// </summary>
public void processStd()
{
    this.processProfileCustomer();
    this.processOnlySellTo();
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processProfileCustomer()
    {
        QueryRun                qr;
        Query                   query = new Query(queryStr(METProfileCustomers));
        QueryBuildDataSource    qbds;
        QueryBuildRange         qbr;
        METPriceChangeTracking  priceChangeTrackingUpdate;
        CustTable               custTable;
        boolean                 validityCheck;

        if(priceChangeTrackingOrig.InventSiteId)
        {
            qbds = query.dataSourceTable(tableNum(CustTable));
            qbr = qbds.rangeField(fieldNum(CustTable, InventSiteId));
            qbr.value(queryValue(priceChangeTrackingOrig.InventSiteId));
        }

        qr = new QueryRun(query);

        while(qr.next())
        {
            custTable = qr.get(tableNum(custTable));
        
            //1. Execute the Item/Site validity check
            validityCheck = this.ItemSiteValidation(priceChangeTrackingOrig.ItemId, custTable.InventSiteId);

            if(validityCheck)
            {
                //update values for processing, but dont committ to DB
                buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);
                priceChangeTrackingUpdate.PriceDiscAccountRelation  = custTable.AccountNum;
                priceChangeTrackingUpdate.InventSiteId              = custTable.InventSiteId;

                this.createPriceDataFeedAll(priceChangeTrackingUpdate, 1, METConstants::emptyString);
            }
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processOnlySellTo()
    {
        //Table
        this.processOnlySellToTable();

        //Group
        this.processOnlySellToGroup();

        //Site
        this.processOnlySellToSite();

        //State
        this.processOnlySellToState();
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processOnlySellToTable()
    {
        METSalesOrderGuideItem  salesOrderGuideItem;
        boolean                 validityCheck;
        str                     message;
        METPriceChangeTracking priceChangeTrackingUpdate;

        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);

        //Table
        while select Reference
            from salesOrderGuideItem
            where   salesOrderGuideItem.ItemId          == priceChangeTrackingOrig.ItemId
            &&      salesOrderGuideItem.LineType        == METSalesOrderGuideInclusion::Include
            &&      salesOrderGuideItem.ReferenceType   == METSalesOrderGuideReferenceType::Customer
        {
            //3. ValidityCheck is True, Work though combinations of "Do not sell to" and find a reason to change "validityCheck = false"
            [validityCheck, message] = this.customerItemValidationDoNotSellTo(salesOrderGuideItem.Reference, priceChangeTrackingOrig.ItemId);

            if(validityCheck)
            {
                priceChangeTrackingUpdate.PriceDiscAccountRelation = salesOrderGuideItem.Reference;

                this.createPriceDataFeedAll(priceChangeTrackingUpdate, 1, METConstants::emptyString);
            }
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processOnlySellToGroup()
    {
        METSalesOrderGuideItem  salesOrderGuideItem;
        METCustTable            metCustTable;
        boolean                 validityCheck;
        str                     message;
        METPriceChangeTracking  priceChangeTrackingUpdate;

        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);

        //Group
        while select AccountNum 
            from metCustTable
        exists join salesOrderGuideItem
            where   salesOrderGuideItem.Reference       == metCustTable.CustOperGroupId
            &&      salesOrderGuideItem.ItemId          == priceChangeTrackingOrig.ItemId
            &&      salesOrderGuideItem.LineType        == METSalesOrderGuideInclusion::Include
            &&      salesOrderGuideItem.ReferenceType   == METSalesOrderGuideReferenceType::CustomerOperationsGroup
        {
            //3. ValidityCheck is True, Work though combinations of "Do not sell to" and find a reason to change "validityCheck = false"
            [validityCheck, message] = this.customerItemValidationDoNotSellTo(metCustTable.AccountNum, priceChangeTrackingOrig.ItemId);

            if(validityCheck)
            {
                priceChangeTrackingUpdate.PriceDiscAccountRelation = metCustTable.AccountNum;

                this.createPriceDataFeedAll(priceChangeTrackingUpdate, 1, METConstants::emptyString);
            }
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processOnlySellToSite()
    {
        METSalesOrderGuideItem  salesOrderGuideItem;
        boolean                 validityCheck;
        str                     message;
        CustTable               custTable;
        METPriceChangeTracking  priceChangeTrackingUpdate;

        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);

        //Site
        while select AccountNum
            from    custTable
        exists join salesOrderGuideItem
            where   salesOrderGuideItem.Reference       == custTable.inventSiteId
            &&      salesOrderGuideItem.ItemId          == priceChangeTrackingOrig.ItemId
            &&      salesOrderGuideItem.LineType        == METSalesOrderGuideInclusion::Include
            &&      salesOrderGuideItem.ReferenceType   == METSalesOrderGuideReferenceType::Site
        {
            //3. ValidityCheck is True, Work though combinations of "Do not sell to" and find a reason to change "validityCheck = false"
            [validityCheck, message] = this.customerItemValidationDoNotSellTo(custTable.AccountNum, priceChangeTrackingOrig.ItemId);

            if(validityCheck)
            {
                priceChangeTrackingUpdate.PriceDiscAccountRelation = custTable.AccountNum;

                this.createPriceDataFeedAll(priceChangeTrackingUpdate, 1, METConstants::emptyString);
            }
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processOnlySellToState()
    {
        boolean                 validityCheck;
        str                     message;
        METSalesOrderGuideItem  salesOrderGuideItem;
        CustTable               custTable;
        LogisticsPostalAddress  address;
        DirPartyLocation        partyLocation;
        METPriceChangeTracking  priceChangeTrackingUpdate;
        FieldId                 denormalizedFieldId;

        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);

        denormalizedFieldId = DirPartyLocation::denormalizedRoleFieldId(LogisticsLocationRoleType::Delivery);

        while select AccountNum
            from    custTable
        
            exists join partyLocation
            where partyLocation.Party               == custTable.Party
            &&  partyLocation.IsPostalAddress       == NoYes::Yes
            &&  partyLocation.(denormalizedFieldId) == true

            exists join address 
            where address.Location  ==  partyLocation.Location

            exists join salesOrderGuideItem
            where   salesOrderGuideItem.Reference       == address.state
            &&      salesOrderGuideItem.ItemId          == priceChangeTrackingOrig.ItemId
            &&      salesOrderGuideItem.LineType        == METSalesOrderGuideInclusion::Include
            &&      salesOrderGuideItem.ReferenceType   == METSalesOrderGuideReferenceType::State
        {
            //3. ValidityCheck is True, Work though combinations of "Do not sell to" and find a reason to change "validityCheck = false"
            [validityCheck, message] = this.customerItemValidationDoNotSellTo(custTable.AccountNum, priceChangeTrackingOrig.ItemId);

            if(validityCheck)
            {
                priceChangeTrackingUpdate.PriceDiscAccountRelation = custTable.AccountNum;

                this.createPriceDataFeedAll(priceChangeTrackingUpdate, 1, METConstants::emptyString);
            }
        }

    }

/// <summary>
/// Get the Id of the record that caused the change
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <returns>Id of the record</returns>
public METChangeCode getChangeCode(METPriceChangeTracking _priceChangeTracking)
{
    return _priceChangeTracking.ItemId;
}

/// <summary>
/// Get the type of the record that caused the change
/// </summary>
/// <returns>Type of the record</returns>
public METCreationType getOriginalCreationType()
{
    return METCreationType::Original;
}

/// <summary>
/// Get the type of the related record
/// </summary>
/// <returns>Related type</returns>
public METCreationType getRelatedCreationType()
{
    return METCreationType::Related;
}

    /// <summary>
    /// Created the Related records
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change track record</param>
    /// <param name = "_lineNumberOrig">Line number of original record</param>
    public void createRelatedComponents(METPriceChangeTracking _priceChangeTracking, LineNumber _lineNumberOrig)
    {
        //Margin Component
        this.createRelatedPriceAdj(_priceChangeTracking, _lineNumberOrig, [RetailDiscountOfferTypeBase::Promotion], METCreationType::RelatedMarginComponent);
        
        //Discount
        this.createRelatedPriceAdj(_priceChangeTracking, _lineNumberOrig, [RetailDiscountOfferTypeBase::Multibuy, RetailDiscountOfferTypeBase::DiscountOffer], METCreationType::RelatedDiscount);

        //Autocharge
        this.createRelatedAutoCharge(_priceChangeTracking, _lineNumberOrig);
    }
